import{_ as s,C as t,o as i,c as n,E as a,a2 as l}from"./chunks/framework.DyLyN3RJ.js";const f=JSON.parse('{"title":"修复提议如何成为宿主动作：响应替换边界的八个探针","description":"","frontmatter":{"date":"2026-11-09T00:00:00.000Z","article_type":"technical-analysis","edition":"research-center","research_question":"恢复或修复的能力边界在哪里：响应适配层实际保留什么，又把哪些保护委托给下层？","title":"修复提议如何成为宿主动作：响应替换边界的八个探针","column":"digital-employee","category":"daily","summary":"八个内部隔离探针区分文本替换、保护委托和宿主应用失败；结果仅支持所测响应适配边界，外部效果与完整系统安全仍未验证。","sources":["https://docs.uipath.com/maestro/automation-cloud/latest/user-guide/process-overview-homepage","https://docs.uipath.com/maestro/automation-cloud/latest/user-guide/how-to-manage-live-case-instances-pause-migrate-and-retry","https://docs.langchain.com/oss/python/langgraph/interrupts.md","https://docs.langchain.com/oss/python/langgraph/fault-tolerance.md","https://arxiv.org/html/2610.20780v1","https://raw.githubusercontent.com/LabRAI/ARIA/ce68c040cca0796b37fa8ae46e2a87a073f64001/src/inference/native/model_hooks.py","https://raw.githubusercontent.com/LabRAI/ARIA/ce68c040cca0796b37fa8ae46e2a87a073f64001/src/repair/rerun.py"],"pageClass":"runtime-v6-article","item_id":"SIG-20261109-002","lifecycle":"Published","cover":"/assets/covers/daily-2026-11-09-sig-20261109-002-final-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/digital-employee/2026-11-09-sig-20261109-002.md","filePath":"zh/digital-employee/2026-11-09-sig-20261109-002.md","lastUpdated":1794226293000}'),d={name:"zh/digital-employee/2026-11-09-sig-20261109-002.md"};function c(h,e,p,m,u,g){const r=t("ArticleCover"),o=t("ArticleTableScroll");return i(),n("div",null,[a(r,{image:"/assets/covers/daily-2026-11-09-sig-20261109-002-final-cover.png",kicker:"研究成果",title:"修复提议如何成为宿主动作：响应替换边界的八个探针",summary:"八个内部隔离探针区分文本替换、保护委托和宿主应用失败；结果仅支持所测响应适配边界，外部效果与完整系统安全仍未验证。",version:"2026-11-09",languageHref:"/en/digital-employee/2026-11-09-sig-20261109-002",languageLabel:"English"}),a(o,{language:"zh"}),e[0]||(e[0]=l('<h1 id="修复提议如何成为宿主动作-响应替换边界的八个探针" tabindex="-1">修复提议如何成为宿主动作：响应替换边界的八个探针 <a class="header-anchor" href="#修复提议如何成为宿主动作-响应替换边界的八个探针" aria-label="Permalink to &quot;修复提议如何成为宿主动作：响应替换边界的八个探针&quot;">​</a></h1><p>一次文本修复已经在拦截器中被标记为“执行”，返回给调用者的响应却可能完全没有变化。两者并不矛盾：前者记录修复层的决定，后者才反映宿主响应是否应用了决定。对维护智能体接入层的工程师，关键问题是：哪个边界保存了什么，哪个边界仍依赖尚未执行的校验？</p><p>本文依据同日完成的研究对象，讨论 ARIA（智能体运行中检查与修正研究系统）固定代码版本的八个隔离探针。结果支持一个有限判断：纯文本替换能保留所测元数据；工具专用响应返回原对象；混合文本与工具响应把保护责任传给下层；不可变响应应用失败时，适配层会把审计更正为未执行。这不是完整系统安全评估，也不说明已经发生的外部写入可以回滚。</p><h2 id="同一个-恢复-可能改变不同的东西" tabindex="-1">同一个“恢复”，可能改变不同的东西 <a class="header-anchor" href="#同一个-恢复-可能改变不同的东西" aria-label="Permalink to &quot;同一个“恢复”，可能改变不同的东西&quot;">​</a></h2><p>先区分对象，再讨论可靠性。UiPath Maestro（流程与案例编排产品）的流程实例文档分别说明暂停、重试与跳转：暂停等待运行步骤结束，重试从最后完成步骤之后继续当前活动，跳转需要后续重试或迁移，并可能要求人工修复变量一致性。案例实例页面则说明，暂停冻结服务时限计时与新任务激活，已有运行任务保持当前状态；重试针对失败任务或转换，迁移保留阶段、数据与审计历史。<a href="https://docs.uipath.com/maestro/automation-cloud/latest/user-guide/process-overview-homepage" target="_blank" rel="noreferrer">流程实例文档</a>、<a href="https://docs.uipath.com/maestro/automation-cloud/latest/user-guide/how-to-manage-live-case-instances-pause-migrate-and-retry" target="_blank" rel="noreferrer">案例实例文档</a>。</p><p>LangGraph（可持久化图式智能体框架）的中断文档说明，恢复会重新执行被中断节点，包括中断前的代码；调用被中断子图的父节点也会重启。容错文档还区分图内状态与外部写入，提示重试可能重复节点，提供方确认丢失时结果仍然未知，需要向提供方核对。<a href="https://docs.langchain.com/oss/python/langgraph/interrupts.md" target="_blank" rel="noreferrer">中断语义</a>、<a href="https://docs.langchain.com/oss/python/langgraph/fault-tolerance.md" target="_blank" rel="noreferrer">容错语义</a>。</p><p>这些是官方文档陈述，本文没有运行上述产品。流程位置、节点重放、待发送文本是不同的变更单位，不能合并为一种事务回滚保证。本文实际测量的是第三种单位：宿主响应交付前的文本适配边界。</p><h2 id="八个探针究竟执行了哪一层" tabindex="-1">八个探针究竟执行了哪一层 <a class="header-anchor" href="#八个探针究竟执行了哪一层" aria-label="Permalink to &quot;八个探针究竟执行了哪一层&quot;">​</a></h2><p>内部实验从下方链接固定的代码版本提取响应适配函数及辅助函数，以合成响应对象调用它们。文本拦截器是故意不实施校验的替身：它请求替换文本，并记录收到的保护标记。实际下层校验器、学习控制器、模型与原生框架均未运行。提取函数和合成输入的意义，是把“适配器自己拒绝什么”与“交给下层拒绝什么”分开，而不是制造一项完整防护测试。<a href="https://github.com/LabRAI/ARIA/blob/ce68c040cca0796b37fa8ae46e2a87a073f64001/src/inference/native/model_hooks.py" target="_blank" rel="noreferrer">固定版本实现</a>、<a href="/joinwell52/assets/evidence/2026-11-09-sig-20261109-002/adapter-probe.json">本次探针记录</a>。</p><table tabindex="0"><thead><tr><th>输入或条件</th><th>内部探针观察</th><th>可以支持的边界判断</th></tr></thead><tbody><tr><td>纯文本响应</td><td>首个选项的文本被替换，响应标识、用量、结束原因、第二选项保留；原输入未变</td><td>所测对象上的复制替换保留这些元数据</td></tr><tr><td>工具专用响应，以及旧式函数调用响应</td><td>返回原对象，并向拦截器传递保护标记和待调用工具</td><td>此路径不把替身返回文本写入宿主</td></tr><tr><td>文本与工具混合</td><td>传递保护标记，但非校验替身仍能使文本被替换，工具字段保留</td><td>该路径的保护依赖下层，不能据此断言真实控制器存在漏洞</td></tr><tr><td>结构化非文本内容</td><td>返回原对象，不调用文本拦截器</td><td>此内容类型绕过文本替换</td></tr><tr><td>禁用干预</td><td>原对象不变，拦截器未被调用</td><td>负对照符合预期</td></tr><tr><td>不可变宿主，失败后放行</td><td>返回原响应，审计改为未执行</td><td>请求成功与宿主应用成功可以分离</td></tr><tr><td>不可变宿主，失败后抛错</td><td>抛出异常，审计同样改为未执行</td><td>失败策略改变调用结果，不把失败写成已交付</td></tr></tbody></table><p>表中工具专用的两种表示分别计为一个用例，共八个。它们是内部、源代码派生的隔离观察，不是独立复现。首次实验因默认字符解码失败，改用明确的字符编码后完成；这项修正属于测试环境处理，不是产品修复。</p><h2 id="为什么-已执行-还需要宿主交付证据" tabindex="-1">为什么“已执行”还需要宿主交付证据 <a class="header-anchor" href="#为什么-已执行-还需要宿主交付证据" aria-label="Permalink to &quot;为什么“已执行”还需要宿主交付证据&quot;">​</a></h2><p>最值得注意的不是替换成功，而是不同层的记录可能回答不同问题。在工具专用用例中，替身的记录仍包含“已执行”和替换内容，但适配器返回原对象，并补充宿主响应未变的边界信息。不可变宿主用例则在应用异常后把“已执行”更正为否，交付内容恢复为原文。只读取一个下层标记，就可能混淆提议、应用与最终返回。</p><p>这是研究解释：审计字段必须连同其记录层级阅读。一个提议被接受，不能替代宿主对象实际变更的证据；宿主交付成功，又不能替代外部提供方已经完成动作的证据。这里没有测量确认绑定的完整方案，也没有证明所有实际响应类型都能正确更正审计。</p><p>ARIA 的修复重跑实现还分别检查原生运行结束与评估结果是否已确定，保留各变体记录并排除未确定评估。它提示了另一条同类边界：运行结束本身不等于任务成功。这是已读固定源码的静态观察，不是本文执行的成对修复重跑。<a href="https://github.com/LabRAI/ARIA/blob/ce68c040cca0796b37fa8ae46e2a87a073f64001/src/repair/rerun.py" target="_blank" rel="noreferrer">修复重跑实现</a>。</p><h2 id="证据与引用-哪些材料回答了哪些问题" tabindex="-1">证据与引用：哪些材料回答了哪些问题 <a class="header-anchor" href="#证据与引用-哪些材料回答了哪些问题" aria-label="Permalink to &quot;证据与引用：哪些材料回答了哪些问题&quot;">​</a></h2><p>公开源码与官方文档是可核查的一手材料，但来自实现方本身，不是第三方独立安全验证。本次探针由研究中心执行，是内部实验，范围仅限提取函数和合成替身；由此推导的分层审计判断属于研究解释。</p><p><a href="https://arxiv.org/html/2610.20780v1" target="_blank" rel="noreferrer">ARIA 预印本第一版</a>报告修复数据构建与执行核验方法；原生后端重建上下文，并不恢复完整宿主状态。论文的修复成功结果仍是作者陈述，本文不把它转换为所测适配器的可靠性指标。论文发布、引用与版本固定建立出处和可追踪性，不建立普遍有效性；所测实现成功也不能替代独立验证。</p><p>可复核的内部证据是相邻的<a href="/joinwell52/assets/evidence/2026-11-09-sig-20261109-002/adapter-probe.json">探针输出</a>。它保留八个用例、输入输出和替身范围说明。本文没有新增模型调用、产品实例实验或外部效果测试。</p><h2 id="尚未验证的宿主与外部效果" tabindex="-1">尚未验证的宿主与外部效果 <a class="header-anchor" href="#尚未验证的宿主与外部效果" aria-label="Permalink to &quot;尚未验证的宿主与外部效果&quot;">​</a></h2><p>这八个用例不能确定实际校验器是否总会拒绝受保护替换，也不能覆盖所有框架响应类型、重试、迁移或审计完整性。尤其不能把混合响应替身的放行行为写成真实生产漏洞：实验故意移除了负责拒绝的下层。</p><p>对需要治理干预的智能体接入层，本文支持分别询问：改变的是待发送文本、宿主返回值，还是外部状态？证据来自提议层、交付层，还是效果确认层？后续仍需真实宿主与完整控制器的联合测试，并核对确认丢失时如何查明外部结果、如何重新检查权限。当前可以保留的结论止于适配边界；不能跨越尚未测量的交付与效果链。</p>',22))])}const _=s(d,[["render",c]]);export{f as __pageData,_ as default};
